(()=>{
const norm=s=>s.normalize('NFC').toLocaleLowerCase('pt-BR').replace(/[^\p{L}\p{N}\s]/gu,' ').replace(/\s+/g,' ').trim();
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let player=null;
const find=text=>window.BoraAudioManifest?.[norm(text)];
function button(text){const a=find(text);return a?`<button type="button" class="audio-phrase" data-audio-id="${a.id}" aria-label="Послушать: ${esc(text)}">▶ Слушать <span class="audio-kind">${a.kind==='native'?'Запись носителя':'Синтез речи · pt-BR'}</span></button>`:''}
function section(c,l,stage=0){if(c.language!=='pt-BR')return '';const phrases=[];const add=t=>{if(!/[а-яё]/i.test(t)&&!phrases.some(p=>norm(p)===norm(t)))phrases.push(t)};l.examples.forEach(([p])=>{add(p);p.split(' / ').forEach(add)});if(stage>=4){l.quiz.forEach(q=>add(q[1][q[2]]));add(l.write[2]);}const extra=l.id==='oi'?['Bom dia!','Boa tarde!','Boa noite!']:l.id==='numeros'?['um','dois','três','quatro','cinco','seis','sete','oito','nove','dez']:l.id==='estar'?['ser','estar']:l.id==='amanha'?['amanhã']:l.id==='onde'?['onde']:[];extra.forEach(add);
return `<details class="audio-library"><summary>🎧 Послушать фразы этого урока</summary><p class="small">«Запись носителя» — живое чтение из учебника. «Синтез речи» — голос Francisca (Бразилия), созданный компьютером.</p>${phrases.map(t=>`<div class="audio-row"><span lang="pt-BR">${esc(t)}</span>${button(t)}</div>`).join('')}</details><div class="audio-player" aria-label="Проигрыватель фраз"><div class="small" id="phrase-caption">Нажми «Слушать» рядом с фразой.</div><audio id="phrase-player" controls preload="none"></audio><label class="small">Скорость <select id="phrase-speed"><option value="1">Обычно</option><option value="0.8">Медленнее · 0,8×</option></select></label><div id="phrase-status" role="status" aria-live="polite"></div><p class="small">Живые записи: UW–Madison, Português para principiantes · <a href="https://creativecommons.org/licenses/by-nc-sa/4.0/" target="_blank" rel="noopener noreferrer">CC BY-NC-SA 4.0</a>.</p></div>`}
function stop(){if(player){player.pause();player.removeAttribute('src');player.load();player=null}}
function bind(){stop();const el=document.querySelector('#phrase-player');if(!el)return;player=el;el.preservesPitch=true;const status=document.querySelector('#phrase-status'),caption=document.querySelector('#phrase-caption'),speed=document.querySelector('#phrase-speed');let selected=null;
speed.onchange=()=>{el.playbackRate=Number(speed.value)};el.onplaying=()=>{status.textContent='Слушаем…'};el.onpause=()=>{if(!el.ended)status.textContent='Пауза. Можно продолжить или повторить фразу.'};el.onended=()=>{status.textContent='Можно повторить фразу или выбрать следующую.'};el.onerror=()=>{status.textContent='Не удалось загрузить запись. Нажми «Слушать» ещё раз.'};
document.querySelectorAll('[data-audio-id]').forEach(b=>b.onclick=async()=>{selected=Object.values(window.BoraAudioManifest).find(a=>a.id===b.dataset.audioId);if(!selected)return;el.pause();el.src=selected.src;el.playbackRate=Number(speed.value);caption.textContent=selected.text+' · '+(selected.kind==='native'?'Запись носителя · UW–Madison':'Синтез речи · Francisca · pt-BR');status.textContent='Загружаю запись…';try{await el.play()}catch{status.textContent='Воспроизведение не началось. Нажми ▶ в плеере.'}})}
window.BoraAudio={button,section,bind,stop};
})();
